package android.view; import java.util.*; public class ViewTreeObserver { public interface OnGlobalLayoutListener {void onGlobalLayout();} final List<OnGlobalLayoutListener> ls=new ArrayList<>(); public boolean isAlive(){return true;} public void addOnGlobalLayoutListener(OnGlobalLayoutListener l){ls.add(l);} public void removeOnGlobalLayoutListener(OnGlobalLayoutListener l){ls.remove(l);} public void layout(){for(OnGlobalLayoutListener l:new ArrayList<>(ls))l.onGlobalLayout();} }